create table public.student_bills(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),student_id uuid not null references public.students(id),category_id uuid not null references public.finance_categories(id),period_id uuid references public.finance_periods(id),invoice_number text not null,amount numeric(14,2) not null check(amount>0),due_date date not null,status text not null default 'OPEN' check(status in('DRAFT','OPEN','PARTIAL','PAID','VOID','OVERDUE')),created_at timestamptz not null default timezone('utc',now()),unique(tenant_id,invoice_number));create index student_bills_tenant_status_idx on public.student_bills(tenant_id,status);alter table public.student_bills enable row level security;revoke all on public.student_bills from anon,authenticated;create policy student_bills_tenant on public.student_bills for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('billing.read','Read billing','View student billing'),('billing.create','Create billing','Create student invoices'),('billing.update','Update billing','Update student invoices'),('billing.delete','Delete billing','Delete student invoices') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF') and p.code like 'billing.%' on conflict do nothing;
